//! Checks the sources generated by `scripts/generate.sh`.
//!
//! The generated files are committed, so they can drift in two ways: their
//! content can disagree with itself (a bug in the generator script) or their
//! version can fall behind the crate version they must belong to. Neither needs
//! the network to detect, so both are ordinary tests; `scripts/generate.sh
//! --check` covers the third case, a stale copy of the published crate.

use keycloak_cli::generated::tags::{KEYCLOAK_CRATE_VERSION, TAGS, TAGS_CARGO};
use keycloak_cli::version;

/// The `keycloak` dependency line of this package's manifest.
fn dependency_line() -> &'static str {
    include_str!("../Cargo.toml")
        .lines()
        .find(|line| line.trim_start().starts_with("keycloak = "))
        .expect("Cargo.toml depends on keycloak")
}

/// The exact crate version `Cargo.toml` pins, e.g. `26.8.100`.
fn pinned_crate_version() -> String {
    let line = dependency_line();
    let start = line
        .find("version = \"=")
        .unwrap_or_else(|| panic!("the keycloak dependency is not pinned exactly: {line}"))
        + "version = \"=".len();
    let rest = &line[start..];
    let end = rest
        .find('"')
        .unwrap_or_else(|| panic!("the version has no closing quote: {line}"));
    rest[..end].to_owned()
}

#[test]
fn generated_version_is_the_pinned_crate_version() {
    // The sources come from the crate `Cargo.toml` pins, not from the package
    // version: a fix release of this CLI does not move the wrapped crate.
    assert_eq!(
        KEYCLOAK_CRATE_VERSION,
        pinned_crate_version(),
        "run scripts/generate.sh after changing the pin"
    );
    assert!(
        dependency_line().contains("default-features = false"),
        "the crate is pulled in without its default features"
    );
}

#[test]
fn the_package_version_wraps_the_pinned_crate_version() {
    // `x.y.(z*100+v)` wraps Keycloak `x.y.z`: the package version and the pinned
    // crate must describe the same Keycloak, whatever their fix release.
    let pinned =
        version::Version::parse(&pinned_crate_version()).expect("the pin is of the form x.y.z");
    assert_eq!(
        version::crate_version().keycloak(),
        pinned.keycloak(),
        "package {} does not wrap the Keycloak version of the pinned crate {}",
        version::CRATE_VERSION,
        pinned
    );
}

#[test]
fn tags_are_unique_kebab_case_and_end_with_the_untagged_bucket() {
    assert!(TAGS.len() > 1, "no tags generated: {TAGS:?}");
    assert_eq!(TAGS.last(), Some(&"none"), "{TAGS:?}");

    let mut sorted = TAGS.to_vec();
    sorted.sort_unstable();
    sorted.dedup();
    assert_eq!(sorted.len(), TAGS.len(), "duplicate tag in {TAGS:?}");

    for tag in TAGS {
        assert!(!tag.is_empty(), "{TAGS:?}");
        assert!(
            tag.strip_prefix("tag-").is_none(),
            "{tag} carries the crate's feature prefix"
        );
        assert!(
            tag.chars()
                .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-'),
            "{tag} is not kebab-case"
        );
    }
}

#[test]
fn tags_cargo_is_the_verbatim_feature_block_of_the_tags() {
    let mut lines = TAGS_CARGO.lines();
    let all = lines.next().expect("tags-all line");
    let features: Vec<String> = TAGS.iter().map(|tag| format!("tag-{tag}")).collect();
    let quoted: Vec<String> = features.iter().map(|name| format!("{name:?}")).collect();

    assert_eq!(all, format!("tags-all = [{}]", quoted.join(", ")));

    let declared: Vec<&str> = lines
        .map(|line| {
            line.strip_suffix(" = []")
                .unwrap_or_else(|| panic!("unexpected line in TAGS_CARGO: {line}"))
        })
        .collect();
    assert_eq!(declared, features);
}

/// The `[features]` block between two sections of `Cargo.toml`.
fn manifest_features() -> String {
    let manifest = include_str!("../Cargo.toml");
    let features = manifest
        .split("[features]")
        .nth(1)
        .expect("Cargo.toml has a [features] section");
    features
        .split("\n[")
        .next()
        .expect("the section ends somewhere")
        .to_owned()
}

#[test]
fn cargo_features_mirror_the_tag_features_of_the_crate() {
    // M8: a tag the crate ships but this package cannot switch on (or the other
    // way round) would mean commands that are generated but never buildable.
    let features = manifest_features();
    let mut declared = Vec::new();
    for line in features.lines() {
        let Some((key, value)) = line.split_once('=') else {
            continue;
        };
        let key = key.trim();
        if key.starts_with("tag-") && key != "tags-all" {
            assert_eq!(
                value.trim(),
                format!("[\"keycloak/{key}\"]"),
                "{key} must enable the crate's own feature"
            );
            declared.push(key.to_owned());
        }
    }
    let expected: Vec<String> = TAGS.iter().map(|tag| format!("tag-{tag}")).collect();
    assert_eq!(
        declared, expected,
        "tag features follow src/generated/tags.rs"
    );

    let tags_all = features
        .lines()
        .find(|line| line.trim_start().starts_with("tags-all"))
        .expect("tags-all exists");
    for feature in &expected {
        assert!(
            tags_all.contains(&format!("{feature:?}")),
            "tags-all does not enable {feature}"
        );
    }
    assert!(features.contains("default = [\"tags-all\"]"), "{features}");
}
